  "privClose": "Zatvori obavijest o privatnosti",
  "privWho": "Tko je odgovoran?",
  "privWhat": "Što koristimo i zašto",
  "privStorage": "Pohrana preglednika",
  "privOther": "Ostale postojeće značajke",
  "privProviders": "Pružatelji usluga i međunarodni prijenosi",
  "privRetention": "Čuvanje i brisanje",
  "privRights": "Vaša prava",
  "noticeReopen": "Obavijest o pohrani",
  "noticeLabel": "Obavijest o pohrani preglednika",
  "noticeText": "Cook koristi pohranu preglednika za značajke kuhanja i prijave koje koristite. Ne dodaje se pohrana za oglašavanje ni analitiku.",
  "noticeClose": "Zatvori obavijest o pohrani",
  "privDraftLabel": "Nacrt — ažurirano 28. listopada 2026.",
  "privDraft": "Značajke računa trenutačno se testiraju. Podatke o voditelju obrade i uslugama u nastavku treba dopuniti prije javnog pokretanja.",
  "privWho1": "Cook vodi [službeni naziv i poštanska adresa voditelja obrade]. Za pitanja i zahtjeve o privatnosti obratite se na [adresa e-pošte za privatnost]. Ove podatke treba dopuniti prije otvaranja registracije.",
  "privWhat1": "Kada izradite račun, koristimo vašu e-poštu, identifikator računa, zapise o autentifikaciji lozinkom i status potvrde kako bismo pružili i zaštitili vaš račun. Lozinke pružatelj autentifikacije obrađuje kao sigurne sažetke; Cook ne pohranjuje čitljive lozinke. Pohranjujemo raspored kuhinje, odabrani jezik, temu i mjerne jedinice kako bismo vratili vaše postavke na svim uređajima. Za račun su potrebni e-pošta i lozinka; recepte možete pregledavati i bez računa.",
  "privWhat2": "Obrada računa i postavki nužna je za pružanje usluge računa koju tražite (članak 6. stavak 1. točka (b) Opće uredbe o zaštiti podataka). Ograničeni zapisi o sigurnosti i sprječavanju zlouporabe mogu se obrađivati na temelju legitimnih interesa (članak 6. stavak 1. točka (f)), u nužnoj mjeri i nakon odvagivanja interesa. Poruke za potvrdu i ponovno postavljanje lozinke servisne su poruke, a ne marketing. Značajka računa ne dodaje oglašavanje ni analitiku.",
  "privStorage1": "Cook koristi sessionStorage za prijenos vaše kuhinje, napretka kuhanja i odabira između stranica u istoj kartici. Kada ste prijavljeni, sadrži i vašu sesiju prijave. Preglednik to obično briše kad sesija kartice završi, ali vraćanje sesije preglednika može to zadržati. Odjava briše Cookove podatke kartice. Zatvaranje obavijesti o pohrani pamti se samo u toj kartici. Cookove vlastite skripte ne postavljaju kolačiće. Vaši pružatelji hostinga ili usluga mogu imati vlastitu sigurnosnu obradu koju treba dokumentirati prije pokretanja.",
  "privStorage2": "U redu i gumb za zatvaranje obavijesti o pohrani samo zatvaraju obavijest. Ne odobravaju analitiku, oglašavanje ni drugo neobavezno praćenje. Svaka buduća pohrana koja nije nužna zahtijevat će zaseban odabir prije početka, uz jednako jednostavno odbijanje i povlačenje.",
  "privOther1": "Trenutačna glasovna značajka popisa recepata na temelju vaše IP adrese od country.is traži približnu državu kako bi odabrala jezik prepoznavanja govora. Ako koristite prepoznavanje putem mikrofona, preglednik može slati zvuk svojem pružatelju prepoznavanja govora. Sastojke možete i upisati. Ove pružatelje, njihove politike i pravnu osnovu ovih značajki treba pregledati prije javnog pokretanja.",
  "privProviders1": "Planirani pružatelj računa: Supabase (upravljani PostgreSQL i autentifikacija) s odabranom regijom baze podataka u EU-u. Pružatelj e-pošte: [pružatelj]. Hosting web-stranice: [pružatelj]. Voditelj obrade mora potvrditi stvarne pružatelje, ugovore o obradi, podizvršitelje, lokacije zapisnika i eventualne prijenose izvan EGP-a. Regija baze podataka u EU-u sama po sebi ne isključuje međunarodne prijenose. Gdje je primjenjivo, navedite odluku o primjerenosti ili ugovorne zaštitne mjere te kako dobiti njihovu kopiju.",
  "privRetention1": "Postavke računa čuvaju se dok je vaš račun aktivan. Brisanje možete zatražiti putem gore navedenog kontakta za privatnost. Prije pokretanja voditelj obrade mora utvrditi postupak odgovaranja na zahtjeve za brisanje, istek nepotvrđenih računa te razdoblja čuvanja sigurnosnih zapisnika i sigurnosnih kopija. Izbrisani podaci mogu ostati u sigurnosnim kopijama s ograničenim pristupom do isteka dokumentiranog razdoblja čuvanja.",
  "privRights1": "Ovisno o primjenjivim uvjetima, možete zatražiti pristup, ispravak, brisanje, ograničenje ili prenosivost, odnosno uložiti prigovor na obradu temeljenu na legitimnom interesu. Obratite se gore navedenom voditelju obrade; na zahtjeve se obično odgovara u roku od mjesec dana, a svako zakonito produljenje se objašnjava. Možete podnijeti pritužbu nadzornom tijelu, uključujući mađarski NAIH na naih.hu. Cook ne koristi postavke računa za automatizirane odluke s pravnim ili slično značajnim učincima.",
  "favOnly": "Samo favoriti",
