  "Fill the pot": "Napunite lonac",
  "Fill the large pot with # L cold water. Don't add oil.": "Veliki lonac napunite s # l hladne vode. Ne dodajte ulje.",
  "Pot filled": "Lonac napunjen",
  "Put it on the stove": "Stavite na štednjak",
  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "Lonac stavite na najveću ploču, uključite na VISOKO i poklopite poklopcem (brže zavrije).",
