  "Let the water come to a full rolling boil. Meanwhile, start the prep.": "Pustite da voda snažno zavrije. U međuvremenu počnite s pripremom.",
  "Big bubbles break the surface all the time": "Veliki mjehurići stalno pucaju na površini",
  "Eggs out of the fridge": "Jaja iz hladnjaka",
  "Take the eggs out of the fridge so they warm up.": "Izvadite jaja iz hladnjaka da se zagriju.",
