  "Roughly chop the walnuts for the layers.": "Krupno nasjeckajte orahe za slojeve.",
  "Tear the sponges into rough pieces. In a deep dish, layer the walnut sponge, half the syrup, half the custard, half the raisins and walnuts; then the cocoa sponge, the rest of the syrup, raisins and walnuts, and finish with the custard.": "Natrgajte biskvite na krupne komade. U duboku posudu slažite slojeve: biskvit s orasima, pola sirupa, pola kreme, pola grožđica i oraha; zatim biskvit s kakaom, ostatak sirupa, grožđice i orahe, a završite kremom.",
